        'Find below query while its running CPU utilization become 100% which cause overhead on all DB servers since the CPU is shared.  As below screen shot query run with parallel 153; that mean query open 153 connection in parallel for the same query  Ask vendor to decrease parallelism degree in it for logical number.     INSERT INTO T_SE_CONTRACTUALDEALCFDMIP ( SELECT DISTINCT NULL ID, CASHFLOWIDBANK, CASHFLOWDATE, CASHFLOWVALUE, CASHFLOWCURRENCY, DEALIDBANK, ROUND(MONTHS_BETWEEN(CASHFLOWDATE,:B3 )/12) RESIDUALMATURITY, ''INSTALLMENT'' CASHFLOWTYPE, NULL OPERATION, NULL OVERRIDDENRECORDID, DAY_DATE SNAPSHOTDATE FROM ( SELECT /* parallel */ DISTINCT A.DAY_DATE DAY_DATE, A.ACCOUNT_NUMBER||P.INS_SEQ CASHFLOWIDBANK, (CASE WHEN P.MAT_DATE <= :B3 THEN :B2 ELSE P.MAT_DATE END) CASHFLOWDATE, A.ACCOUNT_NUMBER DEALIDBANK, CUR.ALT_CUR_CODE CASHFLOWCURRENCY, SUM (P.INS_BAL P.PROFIT_AMT P.ARREARS_BAL) CASHFLOWVALUE FROM BI_DWH.PIO_MUR_PAY P, BI_DWH.PIO_MUR_TAB A, BI_DWH.PIO_CURRENCIES CUR, T_SE_DEALDMIP WHERE A.DAY_DATE = P.DAY_DATE AND A.COUNTRY_CODE =P.COUNTRY_CODE AND A.INST_CODE = P.INST_CODE AND A.BRA_CODE = P.BRA_CODE AND A.CUS_NUM = P.CUS_NUM AND A.CUR_CODE = P.CUR_CODE AND A.LED_CODE = P.LED_CODE AND A.SUB_ACCT_CODE =P.SUB_ACCT_CODE AND A.REF_TYPE = P.REF_TYPE AND A.REF_YEAR = P.REF_YEAR AND A.REF_NUM = P.REF_NUM AND A.ACCOUNT_NUMBER =P.ACCOUNT_NUMBER AND A.DAY_DATE = CUR.DAY_DATE( ) AND A.COUNTRY_CODE = CUR.COUNTRY_CODE( ) AND A.INST_CODE = CUR.INST_CODE( ) AND A.CUR_CODE = CUR.CUR_CODE( ) AND A.MURABAHA_STA IN (''1'', ''3'', ''7'') AND A.DAY_DATE = :B1 AND A.ACCOUNT_NUMBER = DEALIDBANK AND A.DAY_DATE = SNAPSHOTDATE GROUP BY A.DAY_DATE, A.ACCOUNT_NUMBER||P.INS_SEQ , P.MAT_DATE , A.ACCOUNT_NUMBER , CUR.ALT_CUR_CODE ) )',
        'Dear Tawfiq,    Based on our web session and the recommendation of @Mohammed Ramahi, kindly note that line 298 in the procedure LOXON.FILL_T_SE_CONTRACTDEALCFDMIP has been changed from /*+ parallel */ to /*+ parallel(8) */ , kindly check & confirm.    Best Regards,',
